1. Manifest.xml:
```xml
<manifest version="2.0">
  <manifest>
    <backgroundColor>white</backgroundColor>
    <usescript>
      <script>
        // Basic hook for window capture
        <script>
          const capture = new CameraWindow(null);
          const src = capture.getSource();
          src.requestAnimationFrame(() => {
            // Capture video
            const video = new MediaStream(src);
            intime = (video.getTime() - video.getTime()) / 1000.0;
            const url = video.toString();
            const link = document.createElement('a');
            link.href = url;
            link.download = 'screenshot.mp4';
            link.click();
          });
          capture.show();
        </script>
